import { readdir, readFile } from 'node:fs/promises';
import { join, relative, sep } from 'node:path';

import { MANIFEST_FILE, TAGS_DIR, loadCorpus } from './store.ts';

/**
 * The corpus license manifest, `LICENSES.json`. Every corpus file is generated by
 * `render-corpus.ts`, written by hand in this repository (`authored`), or a third-party file
 * under an open license (`thirdParty`). Only openly licensed photos may be added, each with an
 * entry here.
 */
export const LICENSES_FILE = 'LICENSES.json';

/** SPDX ids of the licenses a third-party corpus file may carry. */
export const OPEN_LICENSES = [
  'CC0-1.0',
  'CC-BY-2.0',
  'CC-BY-3.0',
  'CC-BY-4.0',
  'CC-BY-SA-2.0',
  'CC-BY-SA-3.0',
  'CC-BY-SA-4.0',
] as const;
export type OpenLicense = (typeof OPEN_LICENSES)[number];

export interface ThirdPartyFile {
  /** Path inside the corpus directory, with `/` separators. */
  readonly file: string;
  readonly title: string;
  readonly author: string;
  /** Where the file was obtained, as a URL. */
  readonly source: string;
  readonly license: OpenLicense;
}

export interface LicenseManifest {
  /** Files written by hand in this repository, such as the README. */
  readonly authored: readonly string[];
  readonly thirdParty: readonly ThirdPartyFile[];
}

export interface LicenseAudit {
  /** Corpus files that are neither generated nor listed in the license manifest. */
  readonly unlisted: readonly string[];
  /** License manifest entries whose file is not in the corpus. */
  readonly missing: readonly string[];
}

export async function readLicenseManifest(dir: string): Promise<LicenseManifest> {
  const path = join(dir, LICENSES_FILE);
  return parseLicenseManifest(JSON.parse(await readFile(path, 'utf8')), path);
}

/** Checks that every corpus file is generated or has a license manifest entry, and vice versa. */
export async function auditCorpusLicenses(dir: string): Promise<LicenseAudit> {
  const [corpus, licenses, files] = await Promise.all([
    loadCorpus(dir),
    readLicenseManifest(dir),
    listFiles(dir),
  ]);
  const generated = new Set([
    MANIFEST_FILE,
    ...corpus.manifest.cases.flatMap((id) => [`${TAGS_DIR}/${id}.json`, `${TAGS_DIR}/${id}.png`]),
  ]);
  const listed = new Set([...licenses.authored, ...licenses.thirdParty.map(({ file }) => file)]);
  const present = new Set(files);
  return {
    unlisted: files.filter((file) => !generated.has(file) && !listed.has(file)),
    missing: [...listed].filter((file) => !present.has(file)).sort(),
  };
}

async function listFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { recursive: true, withFileTypes: true });
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => relative(dir, join(entry.parentPath, entry.name)).split(sep).join('/'))
    .sort();
}

function parseLicenseManifest(json: unknown, path: string): LicenseManifest {
  const problem = licenseManifestProblem(json);
  if (problem !== null) throw new Error(`${path} is not a corpus license manifest: ${problem}`);
  return json as LicenseManifest;
}

function licenseManifestProblem(json: unknown): string | null {
  if (!isRecord(json)) return 'expected an object';
  const { authored, thirdParty } = json;
  if (!Array.isArray(authored) || !authored.every((file) => typeof file === 'string')) {
    return 'authored must be a list of file paths';
  }
  if (!Array.isArray(thirdParty)) return 'thirdParty must be a list';
  for (const [index, entry] of (thirdParty as unknown[]).entries()) {
    const at = `thirdParty[${String(index)}]`;
    if (!isRecord(entry)) return `${at} must be an object`;
    for (const key of ['file', 'title', 'author', 'source'] as const) {
      const value = entry[key];
      if (typeof value !== 'string' || value.trim() === '') {
        return `${at}.${key} must be a non-empty string`;
      }
    }
    if (!URL.canParse(String(entry['source']))) return `${at}.source must be a URL`;
    if (!(OPEN_LICENSES as readonly unknown[]).includes(entry['license'])) {
      return `${at}.license must be one of ${OPEN_LICENSES.join(', ')}`;
    }
  }
  return null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
